  "problemen": [],
  "rubrieken": {
   "8": [
    {
     "soort": "kop",
     "tekst": "8.2 Maatregelen ter beheersing van blootstelling"
    },
    {
     "soort": "veld",
     "kopje": "Inhalatiebescherming",
     "tekst": "Indien nodig, gebruik een luchtzuiverend gezichtsmasker in geval van ademhalingsrisico’s."
    },
    {
     "soort": "veld",
     "kopje": "Huidbescherming",
     "tekst": "Met nitril-handschoenen (EN 374) hanteren. Minimale doorbraaktijd van > 480 minuten, dikte 0,35mm. Handschoenen voor gebruik goed controleren. Handschoenen netjes uittrekken zonder de buitenkant aan te raken met de blote hand. De geschiktheid voor een specifieke werkplek moet worden overlegd met de fabrikant van de beschermhandschoenen. Was en droog de handen."
    },
    {
     "soort": "veld",
     "kopje": "Oogbescherming",
     "tekst": "Oogspoelfles met zuiver water binnen bereik houden. Gebruik een nauw aansluitende veiligheidsbril (EN 166). Een volgelaatsscherm en beschermend pak dragen bij uitzonderlijke verwerkingsproblemen."
    },
    {
     "soort": "veld",
     "kopje": "Overige bescherming",
     "tekst": "Gebruik niet doorlaatbare beschermende kleding die bestand is tegen dit product. De keuze van specifieke onderdelen zoals gelaatsmasker, handschoenen, laarzen, schort of volledig pak hangt af van de werkzaamheden."
    },
    {
     "soort": "veld",
     "kopje": "Beheersing van milieublootstelling",
     "tekst": "Voldoe aan de relevante milieureglementeringen die het lozen in lucht, water en grond beperken. Bescherm het milieu door juiste controlemaatregelen toe te passen om uitstoot te voorkomen of te beperken. Voor meer informatie, zie rubrieken 6 en 13."
    },
    {
     "soort": "veld",
     "kopje": "Technische maatregelen",
     "tekst": "Het beschermingsniveau en soorten van maatregelen zijn afhankelijk van de omstandigheden op de werkplek. Er moet voor adequate ventilatie gezorgd worden zodat de blootstellingslimieten niet overschreden worden. Voor meer informatie, zie rubriek 7."
    }
   ],
   "4": [
    {
     "soort": "kop",
     "tekst": "4.1 Beschrijving van de eerstehulpmaatregelen"
    },
    {
     "soort": "alinea",
     "tekst": "Steeds zo spoedig mogelijk medisch advies inwinnen in geval van ernstige of aanhoudende stoornissen."
    },
    {
     "soort": "veld",
     "kopje": "Huidcontact",
     "tekst": "Verontreinigde kleding uittrekken, eerst spoelen met veel water, dan zonodig naar arts vervoeren."
    },
    {
     "soort": "veld",
     "kopje": "Oogcontact",
     "tekst": "Eerst langdurig spoelen met water (contactlenzen verwijderen mits makkelijk mogelijk), dan naar arts brengen."
    },
    {
     "soort": "veld",
     "kopje": "Inslikken",
     "tekst": "Mond laten spoelen, GEEN braken opwekken en onmiddellijk naar ziekenhuis vervoeren."
    },
    {
     "soort": "veld",
     "kopje": "Inademing",
     "tekst": "Rechtop laten zitten, frisse lucht, rust en naar ziekenhuis vervoeren."
    },
    {
     "soort": "kop",
     "tekst": "4.2 Belangrijkste acute en uitgestelde symptomen en effecten"
    },
    {
     "soort": "veld",
     "kopje": "Huidcontact",
     "tekst": "roodheid, pijn"
    },
    {
     "soort": "veld",
     "kopje": "Oogcontact",
     "tekst": "roodheid, pijn, slecht zien"
    },
    {
     "soort": "veld",
     "kopje": "Inslikken",
     "tekst": "diarree, hoofdpijn, buikkrampen, slaperigheid, braken"
    },
    {
     "soort": "veld",
     "kopje": "Inademing",
     "tekst": "keelpijn, hoesten, kortademigheid, hoofdpijn"
    },
    {
     "soort": "kop",
     "tekst": "4.3 Vermelding van de vereiste onmiddellijke medische verzorging en speciale behandeling"
    },
    {
     "soort": "alinea",
     "tekst": "geen"
    }
   ],
   "6": [
    {
     "soort": "kop",
     "tekst": "6.1 Persoonlijke voorzorgsmaatregelen, beschermde uitrusting en noodprocedures"
    },
    {
     "soort": "alinea",
     "tekst": "Niet in de gemorste stoffen lopen of ze aanraken. Vermijden om de uitwasemingen, de rook, het stof en de damp in te ademen door boven de wind te blijven. Elk bezoedeld kledingstuk en elke bezoedelde beschermingsuitrusting na gebruik uittrekken en er zich op een veilige manier van ontdoen."
    },
    {
     "soort": "kop",
     "tekst": "6.2 Milieu-voorzorgsmaatregelen"
    },
    {
     "soort": "alinea",
     "tekst": "Niet in riolering of openbare wateren laten wegstromen."
    },
    {
     "soort": "kop",
     "tekst": "6.3 Insluitings- en reinigingsmethoden en -materiaal"
    },
    {
     "soort": "alinea",
     "tekst": "Gemorst product zorgvuldig verzamelen en opslaan in geschikte houders. Eventueel laten opzuigen door absorberend materiaal."
    },
    {
     "soort": "kop",
     "tekst": "6.4 Verwijzing naar andere rubrieken"
    },
    {
     "soort": "alinea",
     "tekst": "Voor verdere informatie zie rubrieken 8 & 13."
    }
   ],
   "5": [
    {
     "soort": "kop",
     "tekst": "5.1 Blusmiddelen"
    },
    {
     "soort": "alinea",
     "tekst": "verneveld water, poeder, schuim, CO2"
    },
    {
     "soort": "kop",
     "tekst": "5.2 Speciale gevaren die door de stof of het mengsel worden veroorzaakt"
    },
    {
     "soort": "alinea",
     "tekst": "geen"
    },
    {
     "soort": "kop",
     "tekst": "5.3 Advies voor brandweerlieden"
    },
    {
     "soort": "veld",
     "kopje": "Te mijden blusmiddelen",
     "tekst": "geen"
    }
   ],
   "13": [
    {
     "soort": "kop",
     "tekst": "13.1 Afvalverwerkingsmethoden"
    },
    {
     "soort": "alinea",
     "tekst": "Lozing is niet toegelaten via riolering. Verwijdering dient te gebeuren door bevoegde diensten. Eventuele richtlijnen van de plaatselijke overheid dienen steeds nageleefd te worden."
    }
   ]
  }
